// Verify the last (rightmost) occurrence of the maximum element in a non-empty array
// - Returns the index i such that:
//   * i < v.len()
//   * v[i] >= v[j] for all j in 0..v.len()
//   * for all k > i, v[k] < v[i]
// This means i is the last position of the max element in v.

verus! {

    fn mlast_maximum(v: &[i32]) -> (i: usize)
        requires v.len() > 0
        ensures i < v.len()
        ensures forall |j: usize| j < v.len() ==> v[i] >= v[j]
        ensures forall |k: usize| k > i && k < v.len() ==> v[k] < v[i]
    {
        // We'll scan from the rightmost index to the left to find the last max.
        // Alternatively, we can scan left to right, tracking the max value seen so far,
        // and update i whenever we find an equal or bigger value, thus getting the last occurrence.

        let mut max_i = 0;
        let mut max_val = v[0];
        let mut idx: usize = 1;
        while idx < v.len() {
            // loop invariant: 0 < idx <= v.len()
            // max_val = max of v[0..idx)
            // max_i is the last index where max occurred in v[0..idx)
            invariant idx <= v.len();
            invariant max_i < idx;
            invariant forall |x: usize| x < idx ==> v[max_i] >= v[x];
            invariant forall |y: usize| y < idx && v[y] == v[max_i] ==> y <= max_i;
            decreases v.len() - idx;

            if v[idx] >= max_val {
                max_val = v[idx];
                max_i = idx;
            }
            idx += 1;
        }

        // After loop:
        // max_i < v.len()
        // v[max_i] >= all values in v
        // max_i chosen as last occurrence of max_val in entire v

        // Need to prove: for all k > max_i, v[k] < v[max_i]
        // Suppose not, then there is some k > max_i with v[k] == v[max_i]
        // But max_i was last index updated whenever equal or greater encountered,
        // so that cannot happen.

        assert forall |k: usize| 
            (k > max_i && k < v.len()) ==> v[k] < v[max_i];

        max_i
    }
}